1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const BASE_SPHINX_SCORE = 2;
8	const MAX_TYPES_FOR_BASE_SCORE = 3;
9	
10	/**
11	 * A card's monster type ignores its rank: Undead Warrior (1) and
12	 * Undead Warrior (3) are the same type.
13	 */
14	const distinctMonsterTypes = (army: Card[]): Set<string> =>
15	  new Set(army.map((card) => card.monster));
16	
17	/**
18	 * Beyond three distinct types the Sphinx scores on a steeper curve.
19	 * Fitted to the examples so far (5 types → 3, 6 types → 5); no example
20	 * yet pins down 4 types, where this formula happens to dip below the base.
21	 *
22	 * Returns the whole score for such an army, not an amount added to the base.
23	 */
24	const scoreForManyTypes = (typeCount: number): number =>
25	  (typeCount - MAX_TYPES_FOR_BASE_SCORE) * 2 - 1;
26	
27	export const scoreArmy = (army: Card[]): number => {
28	  const types = distinctMonsterTypes(army);
29	  if (!types.has(SPHINX)) return 0;
30	
31	  const sphinxCount = army.filter((card) => card.monster === SPHINX).length;
32	  const scorePerSphinx =
33	    types.size <= MAX_TYPES_FOR_BASE_SCORE
34	      ? BASE_SPHINX_SCORE
35	      : scoreForManyTypes(types.size);
36	
37	  return scorePerSphinx * sphinxCount;
38	};
